// </auto-generated>

using Microsoft.EntityFrameworkCore;
using Nafadh_Backend.Enums;
using Nafadh_Backend.Repositories;

namespace Nafadh_Backend.Services
{
    /// <summary>
    /// Real (not stubbed) evaluator for every NFD_BadgeConditionType against a
    /// trainee's live data. Uses the DbContext directly for cross-domain
    /// aggregation queries that don't naturally belong to any single existing
    /// repository — a deliberate, contained exception to the usual
    /// Service-&gt;Repository-&gt;DbContext layering, since badges are inherently
    /// cross-cutting (they read attendance, evaluations, submissions, projects,
    /// and module progress all at once).
    /// </summary>
    public class BadgeEvaluationService : IBadgeEvaluationService
    {
        private readonly Nafadhcontext _context;
        private readonly IBadgeRepository _badgeRepository;

        public BadgeEvaluationService(Nafadhcontext context, IBadgeRepository badgeRepository)
        {
            _context = context;
            _badgeRepository = badgeRepository;
        }

        public async Task EvaluateEnrollmentEvaluationAsync(int enrollmentId)
        {
            var traineeId = await _context.NFD_Enrollments
                .Where(e => e.EnrollmentId == enrollmentId)
                .Select(e => (int?)e.TraineeId)
                .FirstOrDefaultAsync();

            if (traineeId.HasValue)
            {
                await EvaluateTraineeAsync(traineeId.Value);
            }
        }

        public async Task EvaluateTraineeAsync(int traineeId)
        {
            var badges = await _badgeRepository.GetAllBadgesAsync();

            foreach (var badge in badges)
            {
                var alreadyEarned = await _badgeRepository.HasBadgeAsync(traineeId, badge.BadgeId);
                if (alreadyEarned) continue;

                var earned = badge.ConditionType switch
                {
                    NFD_BadgeConditionType.ModulesCompletedInPeriod =>
                        await CheckModulesCompletedInPeriodAsync(traineeId, badge.ConditionValue),

                    NFD_BadgeConditionType.AttendanceStreak =>
                        await CheckAttendanceStreakAsync(traineeId, badge.ConditionValue),

                    NFD_BadgeConditionType.HighScoreCount =>
                        await CheckHighScoreCountAsync(traineeId, badge.ConditionValue),

                    NFD_BadgeConditionType.ProjectCompletion =>
                        await CheckProjectCompletionAsync(traineeId, badge.ConditionValue),

                    NFD_BadgeConditionType.ProgramCompletion =>
                        await CheckProgramCompletionAsync(traineeId),

                    _ => false
                };

                if (earned)
                {
                    await _badgeRepository.GrantBadgeAsync(traineeId, badge.BadgeId);
                }
            }
        }

        // "N modules completed within a rolling 7-day window."
        private async Task<bool> CheckModulesCompletedInPeriodAsync(int traineeId, decimal conditionValue)
        {
            var windowStart = DateTime.UtcNow.AddDays(-7);

            var completedCount = await _context.NFD_TraineeModuleProgresses
                .Where(p => p.TraineeId == traineeId
                    && p.Status == NFD_ModuleProgressStatus.Completed
                    && p.CompletedAt != null
                    && p.CompletedAt >= windowStart)
                .CountAsync();

            return completedCount >= conditionValue;
        }

        // "N consecutive calendar days marked Present, ending on the trainee's
        // most recent attendance day." Combines attendance across every
        // enrollment the trainee has (a trainee has exactly one active
        // enrollment in practice, but this stays correct either way).
        private async Task<bool> CheckAttendanceStreakAsync(int traineeId, decimal conditionValue)
        {
            var presentDates = await _context.NFD_DailyAttendances
                .Where(a => a.Enrollment.TraineeId == traineeId && a.Status == NFD_AttendanceStatus.Present)
                .Select(a => a.Date.Date)
                .Distinct()
                .OrderByDescending(d => d)
                .ToListAsync();

            if (presentDates.Count == 0) return false;

            var streak = 1;
            for (int i = 1; i < presentDates.Count; i++)
            {
                if (presentDates[i - 1].AddDays(-1) == presentDates[i])
                {
                    streak++;
                }
                else
                {
                    break;
                }
            }

            return streak >= conditionValue;
        }

        // "Scored above 90% on at least N graded submissions." Grade is stored as
        // free text (e.g. "92" or "18/20" per the original demo), so this parses
        // both a plain number and a "x/y" fraction; ungradable/unparsable
        // submissions are simply skipped rather than counted as a failure.
        private async Task<bool> CheckHighScoreCountAsync(int traineeId, decimal conditionValue)
        {
            const decimal highScoreThresholdPercent = 90m;

            var grades = await _context.NFD_Submissions
                .Where(s => s.TraineeId == traineeId && s.Status == NFD_SubmissionStatus.Graded && s.Grade != null)
                .Select(s => s.Grade!)
                .ToListAsync();

            int highScoreCount = 0;
            foreach (var raw in grades)
            {
                if (TryParseGradePercent(raw, out var percent) && percent > highScoreThresholdPercent)
                {
                    highScoreCount++;
                }
            }

            return highScoreCount >= conditionValue;
        }

        private static bool TryParseGradePercent(string raw, out decimal percent)
        {
            raw = raw.Trim();

            if (raw.Contains('/'))
            {
                var parts = raw.Split('/');
                if (parts.Length == 2
                    && decimal.TryParse(parts[0], out var numerator)
                    && decimal.TryParse(parts[1], out var denominator)
                    && denominator > 0)
                {
                    percent = (numerator / denominator) * 100m;
                    return true;
                }
            }
            else if (decimal.TryParse(raw, out var flat))
            {
                // A bare number is treated as already being a percentage (0-100).
                percent = flat;
                return true;
            }

            percent = 0;
            return false;
        }

        // "Completed at least N projects" (ProjectMember row on a Completed project).
        private async Task<bool> CheckProjectCompletionAsync(int traineeId, decimal conditionValue)
        {
            var completedCount = await _context.NFD_ProjectMembers
                .Where(pm => pm.TraineeId == traineeId && pm.Project.Status == NFD_ProjectStatus.Completed)
                .CountAsync();

            return completedCount >= conditionValue;
        }

        // "Trainee's overall status is Completed" — the canonical program-completion signal.
        private async Task<bool> CheckProgramCompletionAsync(int traineeId)
        {
            var trainee = await _context.NFD_Trainees.FindAsync(traineeId);
            return trainee != null && trainee.Status == NFD_TraineeStatus.Completed;
        }
    }
}
